(()=>{
  if(!location.pathname.startsWith('/photographer'))return;
  let allowed=false,initialized=false,source=null,sample=null,currentJobId='';
  const LAST_JOB_KEY='photobridge_subject_edit_last_job_v779';
  const css=`.pbSubjectLauncher{width:calc(50% - 8px);min-height:180px;margin:16px 0;border:1px solid #cbd8f4;border-radius:18px;background:#f7f9ff;color:#244da9;padding:20px;font:inherit;text-align:center;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:9px;cursor:pointer}.pbSubjectLauncher span{font-size:30px}.pbSubjectLauncher b{font-size:18px}.pbSubjectLauncher small{color:#687892}.pbSubjectCard{margin:20px 0;padding:22px;border:1px solid #c8d7f5;border-radius:20px;background:#fff;direction:rtl;color:#24314f}.pbSubjectCard[hidden]{display:none!important}.pbSubjectCard h2{margin:0 0 8px;font-size:22px}.pbSubjectCard p{line-height:1.8;color:#62718b}.pbSubjectMode{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin:10px 0 18px}.pbSubjectMode span{padding:6px 10px;border-radius:999px;background:#eef3ff;color:#3157c8;font-size:11px;font-weight:900}.pbSubjectGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.pbSubjectInput{display:grid;gap:9px;font-weight:800;border:1px solid #dbe4f0;border-radius:16px;padding:12px;background:#fbfcff}.pbSubjectCard input[type=file]{display:block;width:100%;padding:10px;border:1px solid #d9e2ef;border-radius:12px;background:#fff}.pbSubjectThumb{height:230px;border-radius:12px;background:#eef3fa;display:grid;place-items:center;overflow:hidden;color:#8a97aa;font-size:12px}.pbSubjectThumb img{width:100%;height:100%;display:block;object-fit:contain;background:#eef3fa}.pbSubjectActions{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.pbSubjectActions button,.pbSubjectDownload{padding:11px 17px;border:0;border-radius:11px;background:#315efb;color:white;font:inherit;font-weight:850;cursor:pointer;text-decoration:none}.pbSubjectActions button.secondary{background:#edf2ff;color:#3156a7}.pbSubjectActions button:disabled{opacity:.45;cursor:not-allowed}.pbSubjectResult{margin-top:12px}.pbSubjectResult img{display:block;max-width:min(100%,520px);max-height:720px;border-radius:16px;border:1px solid #e1e7f0;background:#eef3fa}.pbSubjectResultMeta{display:flex;gap:7px;flex-wrap:wrap;margin:10px 0}.pbSubjectResultMeta span{font-size:10px;padding:5px 8px;border-radius:999px;background:#f0f4fb;color:#52627a}.pbSubjectStatus{min-height:26px;color:#3156a7;font-weight:700}.pbSubjectStatus.error{color:#b13535}.pbSubjectWarning{padding:10px 12px;border-radius:12px;background:#fff8e8;color:#765b1b;font-size:11px}.pbSubjectResultGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.pbSubjectOutputCard{border:1px solid #dfe6f2;border-radius:16px;padding:12px;background:#fbfcff}.pbSubjectOutputCard h3{margin:0 0 8px;font-size:14px}.pbSubjectOutputCard p{margin:0 0 9px;font-size:10px}.pbSubjectOutputCard img{width:100%;height:auto;max-height:640px;object-fit:contain}.pbSubjectOutputError{padding:14px;border-radius:12px;background:#fff1f1;color:#a33636}.pbSubjectResultGrid .pbSubjectDownload{display:inline-flex;margin-top:9px}.pbSubjectRetry{display:inline-flex;margin-top:10px;padding:10px 14px;border:0;border-radius:10px;background:#315efb;color:#fff;font:inherit;font-weight:850;cursor:pointer}.pbSubjectSafeNote{padding:10px 12px;border-radius:12px;background:#eefaf3;color:#23613b;font-size:11px;font-weight:800}@media(max-width:700px){.pbSubjectLauncher{width:100%}.pbSubjectGrid{grid-template-columns:1fr}.pbSubjectThumb{height:190px}.pbSubjectResultGrid{grid-template-columns:1fr}}`;
  const style=document.createElement('style');style.textContent=css;document.head.append(style);
  const esc=s=>String(s||'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const read=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});
  async function request(path,{method='POST',body}={}){const init={method,credentials:'same-origin',headers:{'x-photobridge-portal':'photographer'}};if(body!==undefined){init.headers['content-type']='application/json';init.body=JSON.stringify(body)}const r=await fetch(path,init);let x={};try{x=await r.json()}catch{}if(!r.ok){const e=new Error(x.detail||x.reason||x.error||`HTTP ${r.status}`);e.code=x.error||'';e.data=x;throw e}return x}
  function message(value,error=false){const el=document.querySelector('#pbSubjectStatus');if(el){el.textContent=value;el.classList.toggle('error',error)}}
  function update(section){const btn=section.querySelector('#pbSubjectGenerate');if(btn)btn.disabled=!source||!sample}
  function resultHtml(data,finalData=null,error=''){
    const ai=data.ai||{},final=finalData?.protectedFace||data.protectedFace||null,usd=Number(data.estimatedOpenAiUsd||0);
    return `<div class="pbSubjectSafeNote">خروجی AI روی سرور ذخیره شده است. اگر مرحلهٔ ۳۰×۴۰ خطا بدهد، برای ادامه دوباره هزینهٔ OpenAI پرداخت نمی‌شود.</div><div class="pbSubjectResultGrid"><article class="pbSubjectOutputCard"><h3>خروجی ۱ · خروجی اصلی AI</h3><p>Sunburst Low؛ نتیجه بلافاصله بعد از دریافت از API ذخیره شده است.</p>${ai.url?`<img src="${esc(ai.url)}" alt="خروجی اصلی هوش مصنوعی">`:''}<div class="pbSubjectResultMeta"><span>${esc(data.model||'gpt-image-2.5-sunburst')}</span><span>کیفیت ${esc(data.quality||'low')}</span>${data.outputSize?`<span>${esc(data.outputSize)}</span>`:''}${usd?`<span>هزینه API تقریبی $${usd.toFixed(4)}</span>`:''}</div>${ai.url?`<a class="pbSubjectDownload" href="${esc(ai.url)}" download="${esc(ai.filename||'PhotoBridge-subject-edit-low.jpg')}">دانلود خروجی AI</a>`:''}</article><article class="pbSubjectOutputCard" id="pbSubjectFinalCard"><h3>خروجی ۲ · صورت فایل اصلی</h3>${final?.url?`<p>۳۰×۴۰ سانتی‌متر · ۳۰۰ DPI؛ مرحله دوم از همان خروجی ذخیره‌شده AI ساخته شد.</p><img src="${esc(final.url)}" alt="خروجی با صورت اصلی"><div class="pbSubjectResultMeta"><span>${esc(String(final.width||3543))}×${esc(String(final.height||4724))}</span><span>${esc(String(final.dpi||300))} DPI</span></div><a class="pbSubjectDownload" href="${esc(final.url)}" download="${esc(final.filename||'PhotoBridge-subject-edit-original-face-30x40-300dpi.jpg')}">دانلود خروجی نهایی</a>`:`<div class="pbSubjectOutputError">${esc(error||'مرحلهٔ دوم هنوز اجرا نشده است.')}</div><button type="button" class="pbSubjectRetry" id="pbSubjectRetryFinalize">ادامه از خروجی ذخیره‌شده</button>`}</article></div>`;
  }
  async function finalizeJob(section,data){
    if(!currentJobId)return;
    message('خروجی AI ذخیره شد. حالا مرحلهٔ ۳۰×۴۰ / ۳۰۰ DPI بدون فراخوانی دوباره OpenAI در حال اجراست…');
    try{
      const final=await request('/api/customer/ai-subject-edit/finalize',{body:{jobId:currentJobId}});
      section.querySelector('#pbSubjectResult').innerHTML=resultHtml(data,final,'');
      message('هر دو خروجی آماده‌اند. خروجی دوم از همان نتیجهٔ ذخیره‌شده AI ساخته شد.');
    }catch(e){
      section.querySelector('#pbSubjectResult').innerHTML=resultHtml(data,null,'مرحلهٔ ۳۰×۴۰ خطا داد: '+e.message+' — خروجی AI محفوظ است.');
      message('مرحلهٔ دوم خطا داد، اما خروجی AI از بین نرفته است. روی «ادامه از خروجی ذخیره‌شده» بزن.',true);
      const retry=section.querySelector('#pbSubjectRetryFinalize');if(retry)retry.onclick=()=>finalizeJob(section,data);
    }
  }
  async function restoreJob(section,jobId){
    try{
      const data=await request('/api/customer/ai-subject-edit/jobs/'+encodeURIComponent(jobId),{method:'GET'});currentJobId=data.jobId;localStorage.setItem(LAST_JOB_KEY,currentJobId);section.querySelector('#pbSubjectResult').innerHTML=resultHtml(data,data.protectedFace?data:null,data.lastError||'');
      if(data.protectedFace)message('آخرین کار ذخیره‌شده بازیابی شد؛ هر دو خروجی آماده‌اند.');
      else{message('آخرین خروجی AI بازیابی شد. می‌توانی مرحلهٔ ۳۰×۴۰ را بدون هزینهٔ دوباره ادامه بدهی.');const retry=section.querySelector('#pbSubjectRetryFinalize');if(retry)retry.onclick=()=>finalizeJob(section,data)}
    }catch(e){localStorage.removeItem(LAST_JOB_KEY);message('بازیابی آخرین خروجی ممکن نشد: '+e.message,true)}
  }
  function mount(){if(!allowed)return;const parent=document.querySelector('.photographerAiToolsWorkspace'),grid=parent?.querySelector('.aiServiceActionGrid');if(!grid)return;
    let launcher=parent.querySelector('#pbSubjectLauncher');if(!launcher){launcher=document.createElement('button');launcher.type='button';launcher.id='pbSubjectLauncher';launcher.className='pbSubjectLauncher';launcher.innerHTML='<span aria-hidden="true">✦</span><b>جایگذاری سوژه با GPT Image 2.5</b><small>عکس اصلی + عکس نمونه · تست ادمین</small>';grid.after(launcher)}
    launcher.onclick=()=>{const editor=parent.querySelector('#pbSubjectCard');if(!editor)return;editor.hidden=!editor.hidden;if(!editor.hidden)editor.scrollIntoView({behavior:'smooth',block:'start'})};
    if(parent.querySelector('#pbSubjectCard'))return;
    const section=document.createElement('section');section.id='pbSubjectCard';section.className='pbSubjectCard';section.innerHTML=`<h2>جایگذاری سوژه در عکس نمونه · آزمایشی</h2><p>عکس اول سوژهٔ اصلی و عکس دوم نمونهٔ مقصد است. خروجی پولی AI قبل از شروع مرحلهٔ ۳۰×۴۰ روی سرور ذخیره می‌شود تا در صورت خطا قابل ادامه باشد.</p><div class="pbSubjectMode"><span>GPT Image 2.5 Sunburst</span><span>Quality: Low</span><span>فقط ادمین</span><span>RGB8 PNG ورودی</span><span>Resumable</span></div><div class="pbSubjectGrid"><label class="pbSubjectInput">عکس اصلی سوژه<input id="pbSubjectOriginal" type="file" accept="image/jpeg,image/png,image/webp"><div id="pbSubjectOriginalPreview" class="pbSubjectThumb">هنوز انتخاب نشده</div></label><label class="pbSubjectInput">عکس نمونهٔ مقصد<input id="pbSubjectSample" type="file" accept="image/jpeg,image/png,image/webp"><div id="pbSubjectSamplePreview" class="pbSubjectThumb">هنوز انتخاب نشده</div></label></div><p class="pbSubjectWarning">صورت، زاویهٔ صورت، چشم‌ها، بینی، دهان، حالت خنده، لباس و هویت سوژه باید از عکس اصلی حفظ شوند. مرحلهٔ دوم فقط از خروجی ذخیره‌شده AI ادامه پیدا می‌کند و در Retry دوباره OpenAI فراخوانی نمی‌شود.</p><div class="pbSubjectActions"><button id="pbSubjectGenerate" disabled>ساخت دو خروجی آزمایشی</button><button id="pbSubjectRestore" class="secondary" type="button">بازیابی آخرین خروجی</button><button id="pbSubjectReset" class="secondary" type="button">پاک کردن تست</button></div><p id="pbSubjectStatus" class="pbSubjectStatus" role="status"></p><div id="pbSubjectResult" class="pbSubjectResult"></div>`;
    const heading=parent.querySelector('.photographerAiOtherToolsHead');if(heading){const title=heading.querySelector('h2');if(title)title.textContent='پنج ابزار تکمیلی در یک بخش';const summary=heading.querySelector('p');if(summary)summary.textContent='ترمیم، رنگی‌سازی، افزایش کیفیت، گسترش تصویر و جایگذاری آزمایشی سوژه با GPT Image 2.5.'}launcher.after(section);section.hidden=true;const $=id=>section.querySelector('#'+id);
    $('pbSubjectOriginal').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>15_000_000){message('حجم عکس اصلی باید کمتر از ۱۵ مگابایت باشد.',true);e.target.value='';return}source=await read(f);$('pbSubjectOriginalPreview').innerHTML=`<img src="${esc(source)}" alt="پیش‌نمایش عکس اصلی">`;update(section);message(sample?'هر دو عکس آماده‌اند.':'عکس اصلی آماده است؛ عکس نمونه را انتخاب کن.')};
    $('pbSubjectSample').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>15_000_000){message('حجم عکس نمونه باید کمتر از ۱۵ مگابایت باشد.',true);e.target.value='';return}sample=await read(f);$('pbSubjectSamplePreview').innerHTML=`<img src="${esc(sample)}" alt="پیش‌نمایش عکس نمونه">`;update(section);message(source?'هر دو عکس آماده‌اند.':'عکس نمونه آماده است؛ عکس اصلی سوژه را انتخاب کن.')};
    $('pbSubjectReset').onclick=()=>{source=null;sample=null;currentJobId='';$('pbSubjectOriginal').value='';$('pbSubjectSample').value='';$('pbSubjectOriginalPreview').textContent='هنوز انتخاب نشده';$('pbSubjectSamplePreview').textContent='هنوز انتخاب نشده';$('pbSubjectResult').innerHTML='';message('');update(section)};
    $('pbSubjectRestore').onclick=()=>{const id=localStorage.getItem(LAST_JOB_KEY)||'';if(!id)return message('خروجی ذخیره‌شده‌ای روی این مرورگر پیدا نشد.',true);restoreJob(section,id)};
    $('pbSubjectGenerate').onclick=async()=>{if(!source||!sample)return;const button=$('pbSubjectGenerate');button.disabled=true;$('pbSubjectResult').innerHTML='';message('ورودی‌ها استاندارد می‌شوند و ادیت Low با Sunburst اجرا می‌شود. به محض برگشت API، خروجی ذخیره خواهد شد…');try{const data=await request('/api/customer/ai-subject-edit/render',{body:{originalBase64:source,sampleBase64:sample}});currentJobId=data.jobId;localStorage.setItem(LAST_JOB_KEY,currentJobId);$('pbSubjectResult').innerHTML=resultHtml(data,null,'خروجی AI ذخیره شد؛ مرحلهٔ دوم در حال شروع است.');await finalizeJob(section,data)}catch(e){message('ادیت انجام نشد: '+e.message,true)}finally{button.disabled=!source||!sample}};
  }
  async function authorize(){if(initialized)return;initialized=true;try{const probe=await fetch('/api/customer/ai-subject-composite/access',{credentials:'same-origin',headers:{'x-photobridge-portal':'photographer'}});allowed=probe.ok;if(allowed){mount();new MutationObserver(mount).observe(document.body,{childList:true,subtree:true})}}catch{initialized=false;setTimeout(authorize,3000)}}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',authorize,{once:true});else authorize();
})();
